package com.ruoyi.system.service.impl;
import java.util.List; import java.util.Set; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import com.ruoyi.common.constant.CacheConstants; import com.ruoyi.common.core.redis.RedisCache; import com.ruoyi.common.enums.DesensitizedType; import com.ruoyi.common.exception.ServiceException; import com.ruoyi.system.domain.shop.MallMember; import com.ruoyi.system.domain.shop.MallMemberAddress; import com.ruoyi.system.mapper.shop.MallMemberMapper; import com.ruoyi.system.service.IMallMemberService;
@Service public class MallMemberServiceImpl implements IMallMemberService { @Autowired private MallMemberMapper memberMapper; @Autowired private RedisCache redisCache; public List<MallMember> selectMemberList(MallMember m){List<MallMember> list=memberMapper.selectMemberList(m);for(MallMember i:list)i.setPhone(mask(i.getPhone()));return list;} public MallMember selectMemberById(Long id){MallMember m=memberMapper.selectMemberById(id);if(m!=null)m.setPhone(mask(m.getPhone()));return m;} public List<MallMemberAddress> selectAddresses(Long id){return memberMapper.selectAddressesByMemberId(id);} public int updateStatus(Long id,String status){if(!"0".equals(status)&&!"1".equals(status))throw new ServiceException("会员状态非法");MallMember m=new MallMember();m.setMemberId(id);m.setStatus(status);int rows=memberMapper.updateMemberStatus(m);if(rows>0&&"1".equals(status))revokeTokens(id);return rows;} private void revokeTokens(Long memberId){String indexKey=CacheConstants.APP_MEMBER_TOKENS_KEY+memberId;Set<String> tokens=redisCache.getCacheSet(indexKey);if(tokens!=null)for(String token:tokens)redisCache.deleteObject(CacheConstants.APP_MEMBER_TOKEN_KEY+token);redisCache.deleteObject(indexKey);} private String mask(String phone){return phone==null?null:DesensitizedType.PHONE.desensitizer().apply(phone);} }
